INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','advanced-passives','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"advanced-passives","title":"Advanced passives and causative have/get","level":"C1","order":59,"summary":"Report beliefs impersonally, combine passive with perfect forms, and describe services someone arranges.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Impersonal reporting","Earlier events after a reporting passive","Arrange for someone else to do something","Get-passives and affected experiences"],"rules":[{"title":"Impersonal reporting","explanation":"A reporting passive can avoid naming who holds a view: **It is believed that ...**. Another pattern makes the reported subject the main subject: **She is believed to ...**. These constructions report a claim; they do not establish that it is true.","pattern":"It is believed that she lives here. / She is believed **to live** here.","commonMistakes":["Do not confuse the time of the belief with the time of the event being reported."],"examples":["Report a habitual activity impersonally: “She is believed **to prepare** the visitor guide every week.”","Report a habitual activity impersonally: “She is believed **to restore** the old portrait every week.”"],"skill":"form"},{"title":"Earlier events after a reporting passive","explanation":"Use a **perfect infinitive** when the reported event is earlier than the reporting reference: is believed to have left. A continuous infinitive can show an ongoing activity: is thought to be working. A passive infinitive adds be or have been before the participle.","pattern":"The bridge is thought **to have been built** in 1900.","commonMistakes":["To have built is active; to have been built is passive. The participant’s role determines which is needed."],"examples":["The event was yesterday: “She is believed **to have prepared** the visitor guide then.”","The event was yesterday: “She is believed **to have restored** the old portrait then.”"],"skill":"meaning"},{"title":"Arrange for someone else to do something","explanation":"**Have / get + object + past participle** often describes a service or arranged action. The subject arranges or experiences the action rather than necessarily performing it. Get is often less formal. The causative verb carries tense.","pattern":"We **had the roof repaired**.","commonMistakes":["We had repaired the roof is past perfect active and normally says we did the repair; it is a different structure."],"examples":["Someone else did the task for us. Complete the causative: “We had the visitor guide **prepared**.”","Someone else did the task for us. Complete the causative: “We had the old portrait **restored**.”"],"skill":"contrast"},{"title":"Get-passives and affected experiences","explanation":"Get + participle can form an informal passive, especially for events or changes affecting someone. Causative have can also describe an unwelcome experience that was not arranged, such as having a bag stolen. Meaning and context matter.","pattern":"The parcel **got damaged**. / She **had her bag stolen**.","commonMistakes":["Have something done does not always imply the subject chose or paid for the action."],"examples":["Use a perfect passive infinitive: “The visitor guide is thought to have **been prepared** already.”","Use a perfect passive infinitive: “The old portrait is thought to have **been restored** already.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-advanced-passives"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"3f7c531a-3503-5637-af01-16cbde7ea2fb","topicSlug":"advanced-passives","level":"C1","prompt":"Report a habitual activity impersonally: “She is believed ____ the visitor guide every week.”","choices":[{"id":"A","text":"to prepare"},{"id":"B","text":"prepare"},{"id":"C","text":"prepared"},{"id":"D","text":"preparing"}],"answerId":"A","hint":"After **is believed**, use a suitable **to-infinitive**.","explanation":"The reporting passive **is believed** takes **to prepare** for this habitual activity.","keywords":["reporting-passive-infinitive"],"skill":"reporting-passive-infinitive","contextKey":"advanced-passives-1","fingerprint":"8b8a8f3faceeb1760d14616726908aadb10dead61b4c9a5a888d260d0c145148","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-advanced-passives"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["After **is believed**, use a suitable **to-infinitive**.","The reporting passive **is believed** takes **to prepare** for this habitual activity.","Choose **to prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The reporting passive **is believed** takes **to prepare** for this habitual activity.","B":"The reporting-passive pattern requires a to-infinitive.","C":"A bare past form cannot follow is believed in this construction.","D":"The simple -ing form does not complete this reporting-passive pattern."}}},{"id":"2eae95ab-b06f-5619-a2d8-8edba4c06f3c","topicSlug":"advanced-passives","level":"C1","prompt":"The event was yesterday: “She is believed ____ the visitor guide then.”","choices":[{"id":"A","text":"to had prepared"},{"id":"B","text":"to have preparing"},{"id":"C","text":"to have prepared"},{"id":"D","text":"to has prepared"}],"answerId":"C","hint":"Separate **belief now** from the **event yesterday**.","explanation":"The event precedes the current belief, so use the perfect infinitive **to have prepared**.","keywords":["earlier-reported-event"],"skill":"earlier-reported-event","contextKey":"advanced-passives-1","fingerprint":"5acf9ece5d9fa59ba6e1632c905eb78cfd3d08157dfff1850e2354475e6b2f7f","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-advanced-passives"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Separate **belief now** from the **event yesterday**.","The event precedes the current belief, so use the perfect infinitive **to have prepared**.","Choose **to have prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"To takes base have, not had.","B":"The simple perfect infinitive needs a past participle.","C":"The event precedes the current belief, so use the perfect infinitive **to have prepared**.","D":"An infinitive uses base have, not has."}}},{"id":"fdf97361-e03a-5cce-af26-60915e2114f7","topicSlug":"advanced-passives","level":"C1","prompt":"Someone else did the task for us. Complete the causative: “We had the visitor guide ____.”","choices":[{"id":"A","text":"prepare"},{"id":"B","text":"preparing"},{"id":"C","text":"to prepare"},{"id":"D","text":"prepared"}],"answerId":"D","hint":"The object receives the action, so use a **past participle** after it.","explanation":"**Had + object + prepared** describes the arranged or experienced action on that object.","keywords":["causative-service"],"skill":"causative-service","contextKey":"advanced-passives-1","fingerprint":"620f23f69b526ef8d58bab7319fa275b3c1b5e7690775ecfd2b5f458d435655c","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-advanced-passives"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The object receives the action, so use a **past participle** after it.","**Had + object + prepared** describes the arranged or experienced action on that object.","Choose **prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A bare verb after the object is not this causative have + object + participle pattern.","B":"An -ing form gives a different construction, not the requested completed service.","C":"Have + object + to-infinitive is not the standard causative pattern here.","D":"**Had + object + prepared** describes the arranged or experienced action on that object."}}},{"id":"e313f8f6-cd53-5d2f-ab0a-e4e2150eb258","topicSlug":"advanced-passives","level":"C1","prompt":"Use a perfect passive infinitive: “The visitor guide is thought to have ____ already.”","choices":[{"id":"A","text":"been preparing"},{"id":"B","text":"been prepared"},{"id":"C","text":"being prepared"},{"id":"D","text":"be prepared"}],"answerId":"B","hint":"The thing receives the earlier action: **to have been + past participle**.","explanation":"After to have, **been prepared** makes the infinitive both perfect and passive.","keywords":["perfect-passive-infinitive"],"skill":"perfect-passive-infinitive","contextKey":"advanced-passives-1","fingerprint":"9793a66182be99421a89af5506d969958c312f24d614328719ad5b6c257ed6ae","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-advanced-passives"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The thing receives the earlier action: **to have been + past participle**.","After to have, **been prepared** makes the infinitive both perfect and passive.","Choose **been prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The passive ends in a past participle, not an -ing form.","B":"After to have, **been prepared** makes the infinitive both perfect and passive.","C":"Have requires been, not being.","D":"Base be cannot follow perfect have."}}},{"id":"263acd14-3f7e-5a56-a1b8-1492c1aa3636","topicSlug":"advanced-passives","level":"C1","prompt":"Report a habitual activity impersonally: “She is believed ____ the old portrait every week.”","choices":[{"id":"A","text":"to restore"},{"id":"B","text":"restore"},{"id":"C","text":"restored"},{"id":"D","text":"restoring"}],"answerId":"A","hint":"After **is believed**, use a suitable **to-infinitive**.","explanation":"The reporting passive **is believed** takes **to restore** for this habitual activity.","keywords":["reporting-passive-infinitive"],"skill":"reporting-passive-infinitive","contextKey":"advanced-passives-2","fingerprint":"b9aab1e92915d2234ade8b055c729fb01191dcbc85493ada5e7b29de352077fa","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-advanced-passives"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["After **is believed**, use a suitable **to-infinitive**.","The reporting passive **is believed** takes **to restore** for this habitual activity.","Choose **to restore**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The reporting passive **is believed** takes **to restore** for this habitual activity.","B":"The reporting-passive pattern requires a to-infinitive.","C":"A bare past form cannot follow is believed in this construction.","D":"The simple -ing form does not complete this reporting-passive pattern."}}},{"id":"a4d19c87-2ffd-5904-a51a-315177dffdf6","topicSlug":"advanced-passives","level":"C1","prompt":"The event was yesterday: “She is believed ____ the old portrait then.”","choices":[{"id":"A","text":"to have restoring"},{"id":"B","text":"to have restored"},{"id":"C","text":"to has restored"},{"id":"D","text":"to had restored"}],"answerId":"B","hint":"Separate **belief now** from the **event yesterday**.","explanation":"The event precedes the current belief, so use the perfect infinitive **to have restored**.","keywords":["earlier-reported-event"],"skill":"earlier-reported-event","contextKey":"advanced-passives-2","fingerprint":"2935889bedada4d34f6468775e922a3599df34447fe46faacac7515af96ae1a2","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-advanced-passives"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Separate **belief now** from the **event yesterday**.","The event precedes the current belief, so use the perfect infinitive **to have restored**.","Choose **to have restored**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The simple perfect infinitive needs a past participle.","B":"The event precedes the current belief, so use the perfect infinitive **to have restored**.","C":"An infinitive uses base have, not has.","D":"To takes base have, not had."}}},{"id":"6166ac56-fb39-5bde-a5e3-a34f53c67b9a","topicSlug":"advanced-passives","level":"C1","prompt":"Someone else did the task for us. Complete the causative: “We had the old portrait ____.”","choices":[{"id":"A","text":"restoring"},{"id":"B","text":"to restore"},{"id":"C","text":"restored"},{"id":"D","text":"restore"}],"answerId":"C","hint":"The object receives the action, so use a **past participle** after it.","explanation":"**Had + object + restored** describes the arranged or experienced action on that object.","keywords":["causative-service"],"skill":"causative-service","contextKey":"advanced-passives-2","fingerprint":"88d9a266a9c6284e31f14dc7528ccfb2fee114b717e732b989a3887d97e9b4bf","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-advanced-passives"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The object receives the action, so use a **past participle** after it.","**Had + object + restored** describes the arranged or experienced action on that object.","Choose **restored**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"An -ing form gives a different construction, not the requested completed service.","B":"Have + object + to-infinitive is not the standard causative pattern here.","C":"**Had + object + restored** describes the arranged or experienced action on that object.","D":"A bare verb after the object is not this causative have + object + participle pattern."}}},{"id":"d527db60-fc7f-536a-aaed-07303dd97ec1","topicSlug":"advanced-passives","level":"C1","prompt":"Use a perfect passive infinitive: “The old portrait is thought to have ____ already.”","choices":[{"id":"A","text":"be restored"},{"id":"B","text":"been restoring"},{"id":"C","text":"been restored"},{"id":"D","text":"being restored"}],"answerId":"C","hint":"The thing receives the earlier action: **to have been + past participle**.","explanation":"After to have, **been restored** makes the infinitive both perfect and passive.","keywords":["perfect-passive-infinitive"],"skill":"perfect-passive-infinitive","contextKey":"advanced-passives-2","fingerprint":"61023ef87ec74c7016c3a7a6586540f13405607e7b9cd63af3ade44148b7e96f","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-advanced-passives"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The thing receives the earlier action: **to have been + past participle**.","After to have, **been restored** makes the infinitive both perfect and passive.","Choose **been restored**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Base be cannot follow perfect have.","B":"The passive ends in a past participle, not an -ing form.","C":"After to have, **been restored** makes the infinitive both perfect and passive.","D":"Have requires been, not being."}}},{"id":"bd0d2414-0dd6-5313-a374-19baba8de81c","topicSlug":"advanced-passives","level":"C1","prompt":"Report a habitual activity impersonally: “She is believed ____ the garden fence every week.”","choices":[{"id":"A","text":"measure"},{"id":"B","text":"measured"},{"id":"C","text":"measuring"},{"id":"D","text":"to measure"}],"answerId":"D","hint":"After **is believed**, use a suitable **to-infinitive**.","explanation":"The reporting passive **is believed** takes **to measure** for this habitual activity.","keywords":["reporting-passive-infinitive"],"skill":"reporting-passive-infinitive","contextKey":"advanced-passives-3","fingerprint":"1397e2d1d13a4a1e049180904d2a50970609a051a036569a19d69141427f18a0","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-advanced-passives"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["After **is believed**, use a suitable **to-infinitive**.","The reporting passive **is believed** takes **to measure** for this habitual activity.","Choose **to measure**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The reporting-passive pattern requires a to-infinitive.","B":"A bare past form cannot follow is believed in this construction.","C":"The simple -ing form does not complete this reporting-passive pattern.","D":"The reporting passive **is believed** takes **to measure** for this habitual activity."}}},{"id":"68bda617-2157-54e3-a11e-6ad203f53673","topicSlug":"advanced-passives","level":"C1","prompt":"The event was yesterday: “She is believed ____ the garden fence then.”","choices":[{"id":"A","text":"to had measured"},{"id":"B","text":"to have measuring"},{"id":"C","text":"to have measured"},{"id":"D","text":"to has measured"}],"answerId":"C","hint":"Separate **belief now** from the **event yesterday**.","explanation":"The event precedes the current belief, so use the perfect infinitive **to have measured**.","keywords":["earlier-reported-event"],"skill":"earlier-reported-event","contextKey":"advanced-passives-3","fingerprint":"efc8517347f8b2c5a513cf8b60c4cdaac6ab7f468571aaf8cb4e1c70f90f6d1b","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-advanced-passives"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Separate **belief now** from the **event yesterday**.","The event precedes the current belief, so use the perfect infinitive **to have measured**.","Choose **to have measured**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"To takes base have, not had.","B":"The simple perfect infinitive needs a past participle.","C":"The event precedes the current belief, so use the perfect infinitive **to have measured**.","D":"An infinitive uses base have, not has."}}},{"id":"bfff9986-d45a-5c6b-aaa8-decff395661a","topicSlug":"advanced-passives","level":"C1","prompt":"Someone else did the task for us. Complete the causative: “We had the garden fence ____.”","choices":[{"id":"A","text":"measuring"},{"id":"B","text":"to measure"},{"id":"C","text":"measured"},{"id":"D","text":"measure"}],"answerId":"C","hint":"The object receives the action, so use a **past participle** after it.","explanation":"**Had + object + measured** describes the arranged or experienced action on that object.","keywords":["causative-service"],"skill":"causative-service","contextKey":"advanced-passives-3","fingerprint":"e088bf40fdef287a0292e355ed7e009c4463600355f9f71cf983431002f49c81","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-advanced-passives"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The object receives the action, so use a **past participle** after it.","**Had + object + measured** describes the arranged or experienced action on that object.","Choose **measured**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"An -ing form gives a different construction, not the requested completed service.","B":"Have + object + to-infinitive is not the standard causative pattern here.","C":"**Had + object + measured** describes the arranged or experienced action on that object.","D":"A bare verb after the object is not this causative have + object + participle pattern."}}},{"id":"ecd8cedb-fa60-53a9-ae8b-8c242ffc1131","topicSlug":"advanced-passives","level":"C1","prompt":"Use a perfect passive infinitive: “The garden fence is thought to have ____ already.”","choices":[{"id":"A","text":"be measured"},{"id":"B","text":"been measuring"},{"id":"C","text":"been measured"},{"id":"D","text":"being measured"}],"answerId":"C","hint":"The thing receives the earlier action: **to have been + past participle**.","explanation":"After to have, **been measured** makes the infinitive both perfect and passive.","keywords":["perfect-passive-infinitive"],"skill":"perfect-passive-infinitive","contextKey":"advanced-passives-3","fingerprint":"29fc18cfafda3bc0889ec904919447814d07ee512fdc4184a793c0df09932bec","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-advanced-passives"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The thing receives the earlier action: **to have been + past participle**.","After to have, **been measured** makes the infinitive both perfect and passive.","Choose **been measured**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Base be cannot follow perfect have.","B":"The passive ends in a past participle, not an -ing form.","C":"After to have, **been measured** makes the infinitive both perfect and passive.","D":"Have requires been, not being."}}},{"id":"5c617bdf-d0cf-53ca-a3a2-28926f400813","topicSlug":"advanced-passives","level":"C1","prompt":"Report a habitual activity impersonally: “She is believed ____ the travel leaflet every week.”","choices":[{"id":"A","text":"translated"},{"id":"B","text":"translating"},{"id":"C","text":"to translate"},{"id":"D","text":"translate"}],"answerId":"C","hint":"After **is believed**, use a suitable **to-infinitive**.","explanation":"The reporting passive **is believed** takes **to translate** for this habitual activity.","keywords":["reporting-passive-infinitive"],"skill":"reporting-passive-infinitive","contextKey":"advanced-passives-4","fingerprint":"9a6451ec2dc7d4e198d78bc978b12103cdb115865ae9e3a9f469e1173053cd6a","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-advanced-passives"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["After **is believed**, use a suitable **to-infinitive**.","The reporting passive **is believed** takes **to translate** for this habitual activity.","Choose **to translate**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A bare past form cannot follow is believed in this construction.","B":"The simple -ing form does not complete this reporting-passive pattern.","C":"The reporting passive **is believed** takes **to translate** for this habitual activity.","D":"The reporting-passive pattern requires a to-infinitive."}}},{"id":"ea3e7d54-2e51-5900-a714-f592ffbc234d","topicSlug":"advanced-passives","level":"C1","prompt":"The event was yesterday: “She is believed ____ the travel leaflet then.”","choices":[{"id":"A","text":"to had translated"},{"id":"B","text":"to have translating"},{"id":"C","text":"to have translated"},{"id":"D","text":"to has translated"}],"answerId":"C","hint":"Separate **belief now** from the **event yesterday**.","explanation":"The event precedes the current belief, so use the perfect infinitive **to have translated**.","keywords":["earlier-reported-event"],"skill":"earlier-reported-event","contextKey":"advanced-passives-4","fingerprint":"0ed7c7ce15a1e3c938f59601ddb06696cf8d1b38a3288d556c0e0e26b424b7f2","source":"seed","provenan